sys_variable_value.value:
(function execute(inputs, outputs) {

    var lifecycle = new AESCommunicationLifecycle();
    var result = lifecycle.schedule(inputs.communication);

    outputs.success = result.success;
    outputs.reason = result.reason || '';

})(inputs, outputs);

